def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]

    divider_colors = {grid[r][0] for r in sep_rows}
    divider_colors.update(grid[0][c] for c in sep_cols)

    counts = {}
    for r in range(h):
        for c in range(w):
            if r not in sep_rows and c not in sep_cols:
                color = grid[r][c]
                counts[color] = counts.get(color, 0) + 1

    background = max(counts, key=counts.get)
    marker = next((color for color in counts if color != background), None)

    out = []
    for ri in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[ri] + 1, row_bounds[ri + 1]
        row = []
        for ci in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[ci] + 1, col_bounds[ci + 1]
            n = sum(grid[r][c] == marker
                    for r in range(r0, r1) for c in range(c0, c1))
            row.append(1 if n >= 2 else background)
        out.append(row)
    return out
